window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-59b9bdcf75475f01"]={"versions": [{"id": "FIG-59b9bdcf75475f01", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm (Timing-/Latenzdiagramm) für parallele Netzwerkknoten bzw. NM-Cluster.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Kommunikationsstack, Modul <code>Nm</code> (Network Management Interface) mit aktivierter Koordinator-Funktionalität (<code>NmCoordinatorSupportEnabled == TRUE</code>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des zeitlich harmonisierten Herunterfahrens heterogener, vernetzter und geschachtelter NM-Cluster (z. B. CAN, FlexRay, LIN) über Gateway-Grenzen hinweg. Das Verfahren kompensiert unterschiedliche cluster-spezifische Shutdown-Zeiten mittels lokaler Verzögerungstimer (<code>coordination delay timer</code>), um ein zeitgleiches Erreichen des Ruhezustands (<code>Network silent</code>) zu garantieren und zyklische Re-Wakeups (Wakeup-Spikes) durch asynchron abschaltende Busse zu verhindern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Entitäten:</strong></li>\n<li><code>Active Gateway</code> (Aktiver NM-Koordinator): Steuernder Gateway-Knoten, der den globalen Shutdown initiiert und das <code>SleepReady</code>-Bit auf aktiv koordinierten Bussen setzt.</li>\n<li><code>Passive Gateway1</code> & <code>Passive Gateway2</code> (Passive NM-Koordinatoren / koordinierte Kanäle): Gateway-Instanzen bzw. NM-Cluster, die das <code>SleepReady</code>-Bit detektieren und ihre lokalen Shutdown-Abläufe synchronisieren.</li>\n<li><code>coordination delay timer</code>: Lokale Timer-Instanz im <code>Nm</code>-Modul pro koordiniertem Kanal.</li>\n<li><code>Shutdown NM-Cluster</code>: Cluster-spezifischer Abschaltprozess der jeweiligen Bus-NMs (z. B. <code>CanNm</code>, <code>FrNm</code>), umfasst den Übergang vom <em>Network Mode</em> über den <em>Prepare Bus-Sleep Mode</em> in den <em>Bus-Sleep Mode</em>.</li>\n<li><strong>Konfigurationsparameter & Zeitbasen:</strong></li>\n<li><code>Nm_GlobalCoordinatorShutdownTime</code> / <code>Nm_GlobalCoordinatorTime</code>: Obergrenze der Zeitdauer, die das langsamste Teilsystem inklusive geschachtelter Kaskaden für den vollständigen Shutdown benötigt (<code>[Nm265]</code>).</li>\n<li>$T_{\\text{delay}}$ (<code>coordination delay timer</code>): Deterministischer Verzug, berechnet gemäß <code>[Nm264]</code>:</li>\n</ul>\n<p class=\"fig-p\">$$T_{\\text{delay}} = Nm\\_GlobalCoordinatorTime - T_{\\text{ClusterShutdown,min}}$$</p>\n<ul class=\"fig-list\">\n<li>Für <code>Passive Gateway2</code> gilt $T_{\\text{ClusterShutdown}} = Nm\\_GlobalCoordinatorShutdownTime \\implies T_{\\text{delay}} = 0$.</li>\n<li><strong>Schnittstellen (APIs & Callbacks):</strong></li>\n<li><code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, value)</code>: API zum Setzen/Rücksetzen des Sleep-Ready-Flags im Control Bit Vector (CBV) der NM-PDU (<code>[Nm267]</code>).</li>\n<li><code>ComM_Nm_NetworkStartIndication()</code> / <code>Nm_NetworkStartIndication()</code>: Schnittstellen zur Weiterleitung von Wakeup-Events an den Communication Manager (<code>ComM</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Shutdown-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alle Knoten auf den beteiligten Teilnetzen melden Einschlafbereitschaft (Keine aktiven Kommunikationsanforderungen im <code>ComM</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationsstart (<code>send SleepReady bit</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der aktive Koordinator setzt das <code>SleepReady</code>-Bit im CBV der jeweiligen Bus-NM-Botschaften auf <code>1</code>.</li>\n<li>Simultan wird auf allen Kanälen der kanalindividuelle <code>coordination delay timer</code> gestartet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phasengesteuerte Verzögerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Kanäle mit kurzer nativer Shutdown-Dauer (<code>Active Gateway</code>, <code>Passive Gateway1</code>) verbleiben für die Dauer ihres jeweiligen <code>coordination delay timer</code> im normalen Kommunikationszustand.</li>\n<li>Der langsamste Kanal (<code>Passive Gateway2</code>) besitzt einen Timer-Wert von <code>0</code> und leitet die Cluster-Deaktivierung unmittelbar ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Cluster-Shutdown (<code>Shutdown NM-Cluster</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Ablauf des jeweiligen <code>coordination delay timer</code> schaltet das <code>Nm</code>-Interface die Freigabe für das lokale BusNm frei; das Teilnetz durchläuft seine native Bus-Sleep-Sequenz (z. B. Ablauf von <code>CanNmWaitBusSleepTime</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschlusszustand (<code>Network silent</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sämtliche koordinierten Busse erreichen exakt gleichzeitig den Zustand vollständiger Inaktivität (Bus-Sleep), Transceiver werden synchron schlafen gelegt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen (Aborted Shutdown gemäß <code>[Nm266]</code>, <code>[Nm267]</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fordert eine Applikation oder ein externer Netzknoten während des Ablaufs von $T_{\\text{delay}}$ oder des Shutdowns Kommunikation an:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Sofortiger Abbruch und Reset des <code>coordination delay timer</code> auf aktivem und passivem Koordinator (<code>[Nm266]</code>).</li>\n<li>Rücksetzen des <code>SleepReady</code>-Bits auf <code>0</code> via <code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, 0)</code> auf allen aktiv koordinierten Kanälen (<code>[Nm267]</code>).</li>\n<li>Abbruch wird über <code>ComM_Nm_NetworkStartIndication()</code> behandelt; der reguläre Netzwerkbetrieb bleibt aktiv.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsmanagement (<code>Nm.epc</code>):</strong></li>\n<li><code>NmGlobalCoordinatorTime</code> muss als Worst-Case-Latenz über alle Bus-Technologien hinweg projektiert werden:</li>\n</ul>\n<p class=\"fig-p\">$$NmGlobalCoordinatorTime \\ge \\max_{i} (T_{\\text{ClusterShutdown}, i})$$</p>\n<p class=\"fig-p\">Hierbei müssen alle Bus-spezifischen Timeouts (z. B. <code>CanNmTimeoutTime</code> + <code>CanNmWaitBusSleepTime</code>, FlexRay Dynamic Segment/Cycle Alignment) sowie Gateway-Routing-Verzögerungen für die NM-PDUs addiert werden.</p>\n<ul class=\"fig-list\">\n<li><strong>Treiber- und Stack-Anforderungen:</strong></li>\n<li>Für alle beteiligten Bus-NMs (<code>CanNm</code>, <code>FrNm</code>, <code>UdpNm</code>) muss die Unterstützung für das Control Bit Vector (CBV) Handling sowie die API <code>&lt;BusNm&gt;_SetSleepReadyBit()</code> aktiviert sein (<code>CanNmSleepReadyBitEnabled == TRUE</code>).</li>\n<li><strong>Implementierungs-Fallstrick (Ping-Pong-Effekt):</strong></li>\n<li>Eine zu kurz konfigurierte <code>NmGlobalCoordinatorTime</code> führt dazu, dass schnelle Cluster vorzeitig einschlafen, während langsame Cluster noch aktiv senden. Der noch aktive Traffic weckt die schlafenden Cluster unmittelbar wieder auf.</li>\n<li><strong>Integrations-Validierung:</strong></li>\n<li>Das Rücksetzen des Timers und das synchrone Löschen des <code>SleepReady</code>-Bits bei transienten Kommunikationsanforderungen (<code>[Nm266]</code>, <code>[Nm267]</code>) muss über HIL-Tests mit injizierten Applikations-Requests während der Delay-Phase verifiziert werden.</li>\n</ul>"}, {"id": "FIG-74a5140d9ac21921", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm (Timing-/Latenzdiagramm) für parallele und kaskadierte Netzwerke.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Kommunikationsstack, Modul <code>Nm</code> (Network Management Interface) mit koordinierter Netzwerkverwaltung (<code>NmCoordinatorSupportEnabled == TRUE</code>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des synchronisierten Herunterfahrens hierarchisch geschachtelter NM-Netzwerke (<code>nested connections</code>) über mehrere Gateways (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>). Durch kanalspezifisch berechnete Verzögerungszeiten (<code>Shutdown Delay Time</code>) wird sichergestellt, dass alle heterogenen Busse trotz unterschiedlicher nativer Abschaltzeiten zeitgleich den Ruhezustand (<code>Network silent</code>) erreichen, um asynchrone Re-Wakeups zu unterbinden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Netzwerk-Entitäten:</strong></li>\n<li><code>GW1 Network1 actively coord. chnl</code> & <code>GW1 Network2 actively coord. chnl</code>: Vom primären Koordinator (GW1) aktiv gesteuerte NM-Kanäle.</li>\n<li><code>GW2 Network2 passively coord. chnl</code>: Auf GW2 passiv koordinierter Kanal, der mit Network2 von GW1 gekoppelt ist.</li>\n<li><code>GW2 Network3 actively coord. chnl</code>: Von GW2 aktiv koordinierter Kanal zur Weiterschaltung in das nachgelagerte Teilnetz.</li>\n<li><code>GW3 Network3 passively coord. chnl</code>: Auf GW3 passiv koordinierter Kanal, gekoppelt mit Network3 von GW2.</li>\n<li><code>GW3 Network4 actively coord. chnl</code>: Von GW3 aktiv koordinierter Kanal zum letzten Teilnetz der Kaskade.</li>\n<li><strong>Zustände, Phasen & Timer:</strong></li>\n<li><code>Shutdown Delay Time</code>: Kanalspezifische Verzögerungsspanne (gelbe Balken), die ein vorzeitiges Abschalten schnellerer Netze verhindert.</li>\n<li><code>Shutdown NM-Network</code>: Eigentlicher Netzwerk-Abschaltprozess (hellblaue Balken) der Bus-NM-Module (Übergang in den Bus-Sleep-Modus).</li>\n<li><code>Network silent</code>: Synchroner Endzustand aller koordinierten Kanäle ohne Busaktivität.</li>\n<li><strong>Konfigurationsparameter & Formeln:</strong></li>\n<li><code>NmGlobalCoordinatorTime</code>: Globale Maximalzeit für den vollständigen Shutdown aller koordinierten und geschachtelten Netze (<code>[Nm265]</code>).</li>\n<li>Berechnung der <code>Shutdown Delay Time</code>: Differenz aus <code>NmGlobalCoordinatorTime</code> und der clusterspezifischen Shutdown-Dauer des Kanals (<code>[Nm264]</code>). Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) beträgt die <code>Shutdown Delay Time</code> 0.</li>\n<li><strong>Ereignisse, Signale & Aktionen:</strong></li>\n<li><code>[ready to shutdown on all channels]</code>: Initialer globaler Trigger, wenn alle Kanäle bereit zum Herunterfahren sind.</li>\n<li><code>{set SleepReady bit, start Shutdown}</code>: Aktion zum Setzen des SleepReady-Bits im CBV und Starten des Shutdown-Ablaufs bzw. Delay-Timers.</li>\n<li><code>[receive SleepReady bit] {forward to actively Chnl}</code>: Weiterleitungsaktion passiver Gateway-Kanäle an die zugeordneten aktiven Kanäle.</li>\n<li><code>last NM vote</code> / <code>last Nm vote</code>: Ablauf des Delay-Timers bzw. letzte NM-PDU vor dem Beginn von <code>Shutdown NM-Network</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Shutdown-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald auf allen Kanälen die Shutdown-Bedingung erfüllt ist (<code>[ready to shutdown on all channels]</code>), initiiert Gateway 1 auf seinen aktiv koordinierten Kanälen den Ablauf: <code>{set SleepReady bit, start Shutdown}</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kaskadierte Signalisierung & Weiterleitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>GW1 setzt das <code>SleepReady</code>-Bit auf <code>Network1</code> und <code>Network2</code>.</li>\n<li>GW2 empfängt auf <code>Network2</code> (passiver Kanal) das <code>SleepReady</code>-Bit und leitet dieses unmittelbar an seinen aktiv koordinierten Kanal <code>Network3</code> weiter (<code>[receive SleepReady bit] {forward to actively Chnl}</code>).</li>\n<li>GW3 empfängt auf <code>Network3</code> (passiver Kanal) das <code>SleepReady</code>-Bit und setzt dieses auf seinem aktiv koordinierten Kanal <code>Network4</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phasengesteuerte Verzögerung (<code>Shutdown Delay Time</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die aktiv koordinierten Kanäle (<code>GW1 Network1</code>, <code>GW1 Network2</code>, <code>GW2 Network3</code>, <code>GW3 Network4</code>) starten ihre jeweilige <code>Shutdown Delay Time</code>.</li>\n<li>Die passiven Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) haben keine Verzögerungszeit (<code>Shutdown Delay Time</code> = 0) und gehen direkt in den Shutdown über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschaltphase (<code>Shutdown NM-Network</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Ablauf der kanalindividuellen <code>Shutdown Delay Time</code> erfolgt der Phasenwechsel (markiert durch <code>last NM vote</code> bzw. <code>last Nm vote</code>).</li>\n<li>Alle Kanäle führen den Shutdown ihres jeweiligen Bus-NMs aus (<code>Shutdown NM-Network</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zum exakt selben Zeitpunkt <code>NmGlobalCoordinatorTime</code> erreichen alle sechs Kanäle den Zustand <code>Network silent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong></li>\n<li><code>[Nm264]</code>: Festlegung und Berechnung der kanalindividuellen Verzögerungszeit (<code>Shutdown Delay Time</code>) aus <code>NmGlobalCoordinatorTime</code> abzüglich der minimalen Shutdown-Zeit des jeweiligen Kanals.</li>\n<li><code>[Nm265]</code>: Definition von <code>NmGlobalCoordinatorTime</code> als Obergrenze für den koordinierten Shutdown aller Netze einschließlich geschachtelter Verbindungen (<code>nested connections</code>).</li>\n<li><code>[Nm266]</code>: Aktive und passive NM-Koordinatoren müssen die Verzögerungstimer zurücksetzen, falls der Shutdown durch Kommunikationsanforderungen abgebrochen wird.</li>\n<li><code>[Nm267]</code>: Bei Abbruch des Shutdowns muss das SleepReady-Bit über <code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, 0)</code> auf allen aktiv koordinierten Kanälen zurückgesetzt werden.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Bei geschachtelten Gateways (<code>GW1 -&gt; GW2 -&gt; GW3</code>) muss die Weiterleitung des <code>SleepReady</code>-Bits von passiven an aktive Kanäle mit minimaler Latenz erfolgen, um Timing-Abweichungen innerhalb von <code>NmGlobalCoordinatorTime</code> zu vermeiden.</li>\n<li>Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) darf keine <code>Shutdown Delay Time</code> konfiguriert werden (Wert 0), da deren Deaktivierung direkt an die koordinierende Gegenstelle gekoppelt ist.</li>\n</ul>"}, {"id": "FIG-00bce61309d6a776", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm (Timing-/Latenzdiagramm) für parallele und kaskadierte Netzwerke.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Kommunikationsstack, Modul <code>Nm</code> (Network Management Interface) mit koordinierter Netzwerkverwaltung (<code>NmCoordinatorSupportEnabled == TRUE</code>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des synchronisierten Herunterfahrens hierarchisch geschachtelter NM-Netzwerke (<code>nested connections</code>) über mehrere Gateways (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>). Durch kanalspezifisch berechnete Verzögerungszeiten (<code>Shutdown Delay Time</code>) wird sichergestellt, dass alle heterogenen Busse trotz unterschiedlicher nativer Abschaltzeiten zeitgleich den Ruhezustand (<code>Network silent</code>) erreichen, um asynchrone Re-Wakeups zu unterbinden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Netzwerk-Entitäten:</strong></li>\n<li><code>GW1 Network1 actively coord. chnl</code> & <code>GW1 Network2 actively coord. chnl</code>: Vom primären Koordinator (GW1) aktiv gesteuerte NM-Kanäle.</li>\n<li><code>GW2 Network2 passively coord. chnl</code>: Auf GW2 passiv koordinierter Kanal, der mit Network2 von GW1 gekoppelt ist.</li>\n<li><code>GW2 Network3 actively coord. chnl</code>: Von GW2 aktiv koordinierter Kanal zur Weiterschaltung in das nachgelagerte Teilnetz.</li>\n<li><code>GW3 Network3 passively coord. chnl</code>: Auf GW3 passiv koordinierter Kanal, gekoppelt mit Network3 von GW2.</li>\n<li><code>GW3 Network4 actively coord. chnl</code>: Von GW3 aktiv koordinierter Kanal zum letzten Teilnetz der Kaskade.</li>\n<li><strong>Zustände, Phasen & Timer:</strong></li>\n<li><code>Shutdown Delay Time</code>: Kanalspezifische Verzögerungsspanne (gelbe Balken), die ein vorzeitiges Abschalten schnellerer Netze verhindert.</li>\n<li><code>Shutdown NM-Network</code>: Eigentlicher Netzwerk-Abschaltprozess (hellblaue Balken) der Bus-NM-Module (Übergang in den Bus-Sleep-Modus).</li>\n<li><code>Network silent</code>: Synchroner Endzustand aller koordinierten Kanäle ohne Busaktivität.</li>\n<li><strong>Konfigurationsparameter & Formeln:</strong></li>\n<li><code>NmGlobalCoordinatorTime</code>: Globale Maximalzeit für den vollständigen Shutdown aller koordinierten und geschachtelten Netze (<code>[Nm265]</code>).</li>\n<li>Berechnung der <code>Shutdown Delay Time</code>: Differenz aus <code>NmGlobalCoordinatorTime</code> und der clusterspezifischen Shutdown-Dauer des Kanals (<code>[Nm264]</code>). Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) beträgt die <code>Shutdown Delay Time</code> 0.</li>\n<li><strong>Ereignisse, Signale & Aktionen:</strong></li>\n<li><code>[ready to shutdown on all channels]</code>: Initialer globaler Trigger, wenn alle Kanäle bereit zum Herunterfahren sind.</li>\n<li><code>{set SleepReady bit, start Shutdown}</code>: Aktion zum Setzen des SleepReady-Bits im CBV und Starten des Shutdown-Ablaufs bzw. Delay-Timers.</li>\n<li><code>[receive SleepReady bit] {forward to actively Chnl}</code>: Weiterleitungsaktion passiver Gateway-Kanäle an die zugeordneten aktiven Kanäle.</li>\n<li><code>last NM vote</code> / <code>last Nm vote</code>: Ablauf des Delay-Timers bzw. letzte NM-PDU vor dem Beginn von <code>Shutdown NM-Network</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Shutdown-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald auf allen Kanälen die Shutdown-Bedingung erfüllt ist (<code>[ready to shutdown on all channels]</code>), initiiert Gateway 1 auf seinen aktiv koordinierten Kanälen den Ablauf: <code>{set SleepReady bit, start Shutdown}</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kaskadierte Signalisierung & Weiterleitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>GW1 setzt das <code>SleepReady</code>-Bit auf <code>Network1</code> und <code>Network2</code>.</li>\n<li>GW2 empfängt auf <code>Network2</code> (passiver Kanal) das <code>SleepReady</code>-Bit und leitet dieses unmittelbar an seinen aktiv koordinierten Kanal <code>Network3</code> weiter (<code>[receive SleepReady bit] {forward to actively Chnl}</code>).</li>\n<li>GW3 empfängt auf <code>Network3</code> (passiver Kanal) das <code>SleepReady</code>-Bit und setzt dieses auf seinem aktiv koordinierten Kanal <code>Network4</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phasengesteuerte Verzögerung (<code>Shutdown Delay Time</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die aktiv koordinierten Kanäle (<code>GW1 Network1</code>, <code>GW1 Network2</code>, <code>GW2 Network3</code>, <code>GW3 Network4</code>) starten ihre jeweilige <code>Shutdown Delay Time</code>.</li>\n<li>Die passiven Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) haben keine Verzögerungszeit (<code>Shutdown Delay Time</code> = 0) und gehen direkt in den Shutdown über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschaltphase (<code>Shutdown NM-Network</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Ablauf der kanalindividuellen <code>Shutdown Delay Time</code> erfolgt der Phasenwechsel (markiert durch <code>last NM vote</code> bzw. <code>last Nm vote</code>).</li>\n<li>Alle Kanäle führen den Shutdown ihres jeweiligen Bus-NMs aus (<code>Shutdown NM-Network</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zum exakt selben Zeitpunkt <code>NmGlobalCoordinatorTime</code> erreichen alle sechs Kanäle den Zustand <code>Network silent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong></li>\n<li><code>[Nm264]</code>: Festlegung und Berechnung der kanalindividuellen Verzögerungszeit (<code>Shutdown Delay Time</code>) aus <code>NmGlobalCoordinatorTime</code> abzüglich der minimalen Shutdown-Zeit des jeweiligen Kanals.</li>\n<li><code>[Nm265]</code>: Definition von <code>NmGlobalCoordinatorTime</code> als Obergrenze für den koordinierten Shutdown aller Netze einschließlich geschachtelter Verbindungen (<code>nested connections</code>).</li>\n<li><code>[Nm266]</code>: Aktive und passive NM-Koordinatoren müssen die Verzögerungstimer zurücksetzen, falls der Shutdown durch Kommunikationsanforderungen abgebrochen wird.</li>\n<li><code>[Nm267]</code>: Bei Abbruch des Shutdowns muss das SleepReady-Bit über <code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, 0)</code> auf allen aktiv koordinierten Kanälen zurückgesetzt werden.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Bei geschachtelten Gateways (<code>GW1 -&gt; GW2 -&gt; GW3</code>) muss die Weiterleitung des <code>SleepReady</code>-Bits von passiven an aktive Kanäle mit minimaler Latenz erfolgen, um Timing-Abweichungen innerhalb von <code>NmGlobalCoordinatorTime</code> zu vermeiden.</li>\n<li>Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) darf keine <code>Shutdown Delay Time</code> konfiguriert werden (Wert 0), da deren Deaktivierung direkt an die koordinierende Gegenstelle gekoppelt ist.</li>\n</ul>"}, {"id": "FIG-0e3f32c265898c55", "releases": ["R4.3.1", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm (Timing-/Latenzdiagramm) für parallele und kaskadierte Netzwerke.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Kommunikationsstack, Modul <code>Nm</code> (Network Management Interface) mit koordinierter Netzwerkverwaltung (<code>NmCoordinatorSupportEnabled == TRUE</code>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des synchronisierten Herunterfahrens hierarchisch geschachtelter NM-Netzwerke (<code>nested connections</code>) über mehrere Gateways (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>). Durch kanalspezifisch berechnete Verzögerungszeiten (<code>Shutdown Delay Time</code>) wird sichergestellt, dass alle heterogenen Busse trotz unterschiedlicher nativer Abschaltzeiten zeitgleich den Ruhezustand (<code>Network silent</code>) erreichen, um asynchrone Re-Wakeups zu unterbinden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Netzwerk-Entitäten:</strong></li>\n<li><code>GW1 Network1 actively coord. chnl</code> & <code>GW1 Network2 actively coord. chnl</code>: Vom primären Koordinator (GW1) aktiv gesteuerte NM-Kanäle.</li>\n<li><code>GW2 Network2 passively coord. chnl</code>: Auf GW2 passiv koordinierter Kanal, der mit Network2 von GW1 gekoppelt ist.</li>\n<li><code>GW2 Network3 actively coord. chnl</code>: Von GW2 aktiv koordinierter Kanal zur Weiterschaltung in das nachgelagerte Teilnetz.</li>\n<li><code>GW3 Network3 passively coord. chnl</code>: Auf GW3 passiv koordinierter Kanal, gekoppelt mit Network3 von GW2.</li>\n<li><code>GW3 Network4 actively coord. chnl</code>: Von GW3 aktiv koordinierter Kanal zum letzten Teilnetz der Kaskade.</li>\n<li><strong>Zustände, Phasen & Timer:</strong></li>\n<li><code>Shutdown Delay Time</code>: Kanalspezifische Verzögerungsspanne (gelbe Balken), die ein vorzeitiges Abschalten schnellerer Netze verhindert.</li>\n<li><code>Shutdown NM-Network</code>: Eigentlicher Netzwerk-Abschaltprozess (hellblaue Balken) der Bus-NM-Module (Übergang in den Bus-Sleep-Modus).</li>\n<li><code>Network silent</code>: Synchroner Endzustand aller koordinierten Kanäle ohne Busaktivität.</li>\n<li><strong>Konfigurationsparameter & Formeln:</strong></li>\n<li><code>NmGlobalCoordinatorTime</code>: Globale Maximalzeit für den vollständigen Shutdown aller koordinierten und geschachtelten Netze (<code>[Nm265]</code>).</li>\n<li>Berechnung der <code>Shutdown Delay Time</code>: Differenz aus <code>NmGlobalCoordinatorTime</code> und der clusterspezifischen Shutdown-Dauer des Kanals (<code>[Nm264]</code>). Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) beträgt die <code>Shutdown Delay Time</code> 0.</li>\n<li><strong>Ereignisse, Signale & Aktionen:</strong></li>\n<li><code>[ready to shutdown on all channels]</code>: Initialer globaler Trigger, wenn alle Kanäle bereit zum Herunterfahren sind.</li>\n<li><code>{set SleepReady bit, start Shutdown}</code>: Aktion zum Setzen des SleepReady-Bits im CBV und Starten des Shutdown-Ablaufs bzw. Delay-Timers.</li>\n<li><code>[receive SleepReady bit] {forward to actively Chnl}</code>: Weiterleitungsaktion passiver Gateway-Kanäle an die zugeordneten aktiven Kanäle.</li>\n<li><code>last NM vote</code> / <code>last Nm vote</code>: Ablauf des Delay-Timers bzw. letzte NM-PDU vor dem Beginn von <code>Shutdown NM-Network</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Shutdown-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald auf allen Kanälen die Shutdown-Bedingung erfüllt ist (<code>[ready to shutdown on all channels]</code>), initiiert Gateway 1 auf seinen aktiv koordinierten Kanälen den Ablauf: <code>{set SleepReady bit, start Shutdown}</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kaskadierte Signalisierung & Weiterleitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>GW1 setzt das <code>SleepReady</code>-Bit auf <code>Network1</code> und <code>Network2</code>.</li>\n<li>GW2 empfängt auf <code>Network2</code> (passiver Kanal) das <code>SleepReady</code>-Bit und leitet dieses unmittelbar an seinen aktiv koordinierten Kanal <code>Network3</code> weiter (<code>[receive SleepReady bit] {forward to actively Chnl}</code>).</li>\n<li>GW3 empfängt auf <code>Network3</code> (passiver Kanal) das <code>SleepReady</code>-Bit und setzt dieses auf seinem aktiv koordinierten Kanal <code>Network4</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phasengesteuerte Verzögerung (<code>Shutdown Delay Time</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die aktiv koordinierten Kanäle (<code>GW1 Network1</code>, <code>GW1 Network2</code>, <code>GW2 Network3</code>, <code>GW3 Network4</code>) starten ihre jeweilige <code>Shutdown Delay Time</code>.</li>\n<li>Die passiven Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) haben keine Verzögerungszeit (<code>Shutdown Delay Time</code> = 0) und gehen direkt in den Shutdown über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschaltphase (<code>Shutdown NM-Network</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Ablauf der kanalindividuellen <code>Shutdown Delay Time</code> erfolgt der Phasenwechsel (markiert durch <code>last NM vote</code> bzw. <code>last Nm vote</code>).</li>\n<li>Alle Kanäle führen den Shutdown ihres jeweiligen Bus-NMs aus (<code>Shutdown NM-Network</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zum exakt selben Zeitpunkt <code>NmGlobalCoordinatorTime</code> erreichen alle sechs Kanäle den Zustand <code>Network silent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong></li>\n<li><code>[Nm264]</code>: Festlegung und Berechnung der kanalindividuellen Verzögerungszeit (<code>Shutdown Delay Time</code>) aus <code>NmGlobalCoordinatorTime</code> abzüglich der minimalen Shutdown-Zeit des jeweiligen Kanals.</li>\n<li><code>[Nm265]</code>: Definition von <code>NmGlobalCoordinatorTime</code> als Obergrenze für den koordinierten Shutdown aller Netze einschließlich geschachtelter Verbindungen (<code>nested connections</code>).</li>\n<li><code>[Nm266]</code>: Aktive und passive NM-Koordinatoren müssen die Verzögerungstimer zurücksetzen, falls der Shutdown durch Kommunikationsanforderungen abgebrochen wird.</li>\n<li><code>[Nm267]</code>: Bei Abbruch des Shutdowns muss das SleepReady-Bit über <code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, 0)</code> auf allen aktiv koordinierten Kanälen zurückgesetzt werden.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Bei geschachtelten Gateways (<code>GW1 -&gt; GW2 -&gt; GW3</code>) muss die Weiterleitung des <code>SleepReady</code>-Bits von passiven an aktive Kanäle mit minimaler Latenz erfolgen, um Timing-Abweichungen innerhalb von <code>NmGlobalCoordinatorTime</code> zu vermeiden.</li>\n<li>Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) darf keine <code>Shutdown Delay Time</code> konfiguriert werden (Wert 0), da deren Deaktivierung direkt an die koordinierende Gegenstelle gekoppelt ist.</li>\n</ul>"}, {"id": "FIG-d34986b7783fb519", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm (Timing-/Latenzdiagramm) für parallele und kaskadierte Netzwerke.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Kommunikationsstack, Modul <code>Nm</code> (Network Management Interface) mit koordinierter Netzwerkverwaltung (<code>NmCoordinatorSupportEnabled == TRUE</code>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des synchronisierten Herunterfahrens hierarchisch geschachtelter NM-Netzwerke (<code>nested connections</code>) über mehrere Gateways (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>). Durch kanalspezifisch berechnete Verzögerungszeiten (<code>Shutdown Delay Time</code>) wird sichergestellt, dass alle heterogenen Busse trotz unterschiedlicher nativer Abschaltzeiten zeitgleich den Ruhezustand (<code>Network silent</code>) erreichen, um asynchrone Re-Wakeups zu unterbinden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Netzwerk-Entitäten:</strong></li>\n<li><code>GW1 Network1 actively coord. chnl</code> & <code>GW1 Network2 actively coord. chnl</code>: Vom primären Koordinator (GW1) aktiv gesteuerte NM-Kanäle.</li>\n<li><code>GW2 Network2 passively coord. chnl</code>: Auf GW2 passiv koordinierter Kanal, der mit Network2 von GW1 gekoppelt ist.</li>\n<li><code>GW2 Network3 actively coord. chnl</code>: Von GW2 aktiv koordinierter Kanal zur Weiterschaltung in das nachgelagerte Teilnetz.</li>\n<li><code>GW3 Network3 passively coord. chnl</code>: Auf GW3 passiv koordinierter Kanal, gekoppelt mit Network3 von GW2.</li>\n<li><code>GW3 Network4 actively coord. chnl</code>: Von GW3 aktiv koordinierter Kanal zum letzten Teilnetz der Kaskade.</li>\n<li><strong>Zustände, Phasen & Timer:</strong></li>\n<li><code>Shutdown Delay Time</code>: Kanalspezifische Verzögerungsspanne (gelbe Balken), die ein vorzeitiges Abschalten schnellerer Netze verhindert.</li>\n<li><code>Shutdown NM-Network</code>: Eigentlicher Netzwerk-Abschaltprozess (hellblaue Balken) der Bus-NM-Module (Übergang in den Bus-Sleep-Modus).</li>\n<li><code>Network silent</code>: Synchroner Endzustand aller koordinierten Kanäle ohne Busaktivität.</li>\n<li><strong>Konfigurationsparameter & Formeln:</strong></li>\n<li><code>NmGlobalCoordinatorTime</code>: Globale Maximalzeit für den vollständigen Shutdown aller koordinierten und geschachtelten Netze (<code>[Nm265]</code>).</li>\n<li>Berechnung der <code>Shutdown Delay Time</code>: Differenz aus <code>NmGlobalCoordinatorTime</code> und der clusterspezifischen Shutdown-Dauer des Kanals (<code>[Nm264]</code>). Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) beträgt die <code>Shutdown Delay Time</code> 0.</li>\n<li><strong>Ereignisse, Signale & Aktionen:</strong></li>\n<li><code>[ready to shutdown on all channels]</code>: Initialer globaler Trigger, wenn alle Kanäle bereit zum Herunterfahren sind.</li>\n<li><code>{set SleepReady bit, start Shutdown}</code>: Aktion zum Setzen des SleepReady-Bits im CBV und Starten des Shutdown-Ablaufs bzw. Delay-Timers.</li>\n<li><code>[receive SleepReady bit] {forward to actively Chnl}</code>: Weiterleitungsaktion passiver Gateway-Kanäle an die zugeordneten aktiven Kanäle.</li>\n<li><code>last NM vote</code> / <code>last Nm vote</code>: Ablauf des Delay-Timers bzw. letzte NM-PDU vor dem Beginn von <code>Shutdown NM-Network</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Shutdown-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald auf allen Kanälen die Shutdown-Bedingung erfüllt ist (<code>[ready to shutdown on all channels]</code>), initiiert Gateway 1 auf seinen aktiv koordinierten Kanälen den Ablauf: <code>{set SleepReady bit, start Shutdown}</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kaskadierte Signalisierung & Weiterleitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>GW1 setzt das <code>SleepReady</code>-Bit auf <code>Network1</code> und <code>Network2</code>.</li>\n<li>GW2 empfängt auf <code>Network2</code> (passiver Kanal) das <code>SleepReady</code>-Bit und leitet dieses unmittelbar an seinen aktiv koordinierten Kanal <code>Network3</code> weiter (<code>[receive SleepReady bit] {forward to actively Chnl}</code>).</li>\n<li>GW3 empfängt auf <code>Network3</code> (passiver Kanal) das <code>SleepReady</code>-Bit und setzt dieses auf seinem aktiv koordinierten Kanal <code>Network4</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phasengesteuerte Verzögerung (<code>Shutdown Delay Time</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die aktiv koordinierten Kanäle (<code>GW1 Network1</code>, <code>GW1 Network2</code>, <code>GW2 Network3</code>, <code>GW3 Network4</code>) starten ihre jeweilige <code>Shutdown Delay Time</code>.</li>\n<li>Die passiven Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) haben keine Verzögerungszeit (<code>Shutdown Delay Time</code> = 0) und gehen direkt in den Shutdown über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschaltphase (<code>Shutdown NM-Network</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Ablauf der kanalindividuellen <code>Shutdown Delay Time</code> erfolgt der Phasenwechsel (markiert durch <code>last NM vote</code> bzw. <code>last Nm vote</code>).</li>\n<li>Alle Kanäle führen den Shutdown ihres jeweiligen Bus-NMs aus (<code>Shutdown NM-Network</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zum exakt selben Zeitpunkt <code>NmGlobalCoordinatorTime</code> erreichen alle sechs Kanäle den Zustand <code>Network silent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong></li>\n<li><code>[Nm264]</code>: Festlegung und Berechnung der kanalindividuellen Verzögerungszeit (<code>Shutdown Delay Time</code>) aus <code>NmGlobalCoordinatorTime</code> abzüglich der minimalen Shutdown-Zeit des jeweiligen Kanals.</li>\n<li><code>[Nm265]</code>: Definition von <code>NmGlobalCoordinatorTime</code> als Obergrenze für den koordinierten Shutdown aller Netze einschließlich geschachtelter Verbindungen (<code>nested connections</code>).</li>\n<li><code>[Nm266]</code>: Aktive und passive NM-Koordinatoren müssen die Verzögerungstimer zurücksetzen, falls der Shutdown durch Kommunikationsanforderungen abgebrochen wird.</li>\n<li><code>[Nm267]</code>: Bei Abbruch des Shutdowns muss das SleepReady-Bit über <code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, 0)</code> auf allen aktiv koordinierten Kanälen zurückgesetzt werden.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Bei geschachtelten Gateways (<code>GW1 -&gt; GW2 -&gt; GW3</code>) muss die Weiterleitung des <code>SleepReady</code>-Bits von passiven an aktive Kanäle mit minimaler Latenz erfolgen, um Timing-Abweichungen innerhalb von <code>NmGlobalCoordinatorTime</code> zu vermeiden.</li>\n<li>Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) darf keine <code>Shutdown Delay Time</code> konfiguriert werden (Wert 0), da deren Deaktivierung direkt an die koordinierende Gegenstelle gekoppelt ist.</li>\n</ul>"}, {"id": "FIG-64a4da16e22aa2e4", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitablaufdiagramm (Timing-/Latenzdiagramm) für parallele und kaskadierte Netzwerke.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Kommunikationsstack, Modul <code>Nm</code> (Network Management Interface) mit koordinierter Netzwerkverwaltung (<code>NmCoordinatorSupportEnabled == TRUE</code>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des synchronisierten Herunterfahrens hierarchisch geschachtelter NM-Netzwerke (<code>nested connections</code>) über mehrere Gateways (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>). Durch kanalspezifisch berechnete Verzögerungszeiten (<code>Shutdown Delay Time</code>) wird sichergestellt, dass alle heterogenen Busse trotz unterschiedlicher nativer Abschaltzeiten zeitgleich den Ruhezustand (<code>Network silent</code>) erreichen, um asynchrone Re-Wakeups zu unterbinden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Netzwerk-Entitäten:</strong></li>\n<li><code>GW1 Network1 actively coord. chnl</code> & <code>GW1 Network2 actively coord. chnl</code>: Vom primären Koordinator (GW1) aktiv gesteuerte NM-Kanäle.</li>\n<li><code>GW2 Network2 passively coord. chnl</code>: Auf GW2 passiv koordinierter Kanal, der mit Network2 von GW1 gekoppelt ist.</li>\n<li><code>GW2 Network3 actively coord. chnl</code>: Von GW2 aktiv koordinierter Kanal zur Weiterschaltung in das nachgelagerte Teilnetz.</li>\n<li><code>GW3 Network3 passively coord. chnl</code>: Auf GW3 passiv koordinierter Kanal, gekoppelt mit Network3 von GW2.</li>\n<li><code>GW3 Network4 actively coord. chnl</code>: Von GW3 aktiv koordinierter Kanal zum letzten Teilnetz der Kaskade.</li>\n<li><strong>Zustände, Phasen & Timer:</strong></li>\n<li><code>Shutdown Delay Time</code>: Kanalspezifische Verzögerungsspanne (gelbe Balken), die ein vorzeitiges Abschalten schnellerer Netze verhindert.</li>\n<li><code>Shutdown NM-Network</code>: Eigentlicher Netzwerk-Abschaltprozess (hellblaue Balken) der Bus-NM-Module (Übergang in den Bus-Sleep-Modus).</li>\n<li><code>Network silent</code>: Synchroner Endzustand aller koordinierten Kanäle ohne Busaktivität.</li>\n<li><strong>Konfigurationsparameter & Formeln:</strong></li>\n<li><code>NmGlobalCoordinatorTime</code>: Globale Maximalzeit für den vollständigen Shutdown aller koordinierten und geschachtelten Netze (<code>[Nm265]</code>).</li>\n<li>Berechnung der <code>Shutdown Delay Time</code>: Differenz aus <code>NmGlobalCoordinatorTime</code> und der clusterspezifischen Shutdown-Dauer des Kanals (<code>[Nm264]</code>). Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) beträgt die <code>Shutdown Delay Time</code> 0.</li>\n<li><strong>Ereignisse, Signale & Aktionen:</strong></li>\n<li><code>[ready to shutdown on all channels]</code>: Initialer globaler Trigger, wenn alle Kanäle bereit zum Herunterfahren sind.</li>\n<li><code>{set SleepReady bit, start Shutdown}</code>: Aktion zum Setzen des SleepReady-Bits im CBV und Starten des Shutdown-Ablaufs bzw. Delay-Timers.</li>\n<li><code>[receive SleepReady bit] {forward to actively Chnl}</code>: Weiterleitungsaktion passiver Gateway-Kanäle an die zugeordneten aktiven Kanäle.</li>\n<li><code>last NM vote</code> / <code>last Nm vote</code>: Ablauf des Delay-Timers bzw. letzte NM-PDU vor dem Beginn von <code>Shutdown NM-Network</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Shutdown-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald auf allen Kanälen die Shutdown-Bedingung erfüllt ist (<code>[ready to shutdown on all channels]</code>), initiiert Gateway 1 auf seinen aktiv koordinierten Kanälen den Ablauf: <code>{set SleepReady bit, start Shutdown}</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kaskadierte Signalisierung & Weiterleitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>GW1 setzt das <code>SleepReady</code>-Bit auf <code>Network1</code> und <code>Network2</code>.</li>\n<li>GW2 empfängt auf <code>Network2</code> (passiver Kanal) das <code>SleepReady</code>-Bit und leitet dieses unmittelbar an seinen aktiv koordinierten Kanal <code>Network3</code> weiter (<code>[receive SleepReady bit] {forward to actively Chnl}</code>).</li>\n<li>GW3 empfängt auf <code>Network3</code> (passiver Kanal) das <code>SleepReady</code>-Bit und setzt dieses auf seinem aktiv koordinierten Kanal <code>Network4</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phasengesteuerte Verzögerung (<code>Shutdown Delay Time</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die aktiv koordinierten Kanäle (<code>GW1 Network1</code>, <code>GW1 Network2</code>, <code>GW2 Network3</code>, <code>GW3 Network4</code>) starten ihre jeweilige <code>Shutdown Delay Time</code>.</li>\n<li>Die passiven Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) haben keine Verzögerungszeit (<code>Shutdown Delay Time</code> = 0) und gehen direkt in den Shutdown über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschaltphase (<code>Shutdown NM-Network</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Ablauf der kanalindividuellen <code>Shutdown Delay Time</code> erfolgt der Phasenwechsel (markiert durch <code>last NM vote</code> bzw. <code>last Nm vote</code>).</li>\n<li>Alle Kanäle führen den Shutdown ihres jeweiligen Bus-NMs aus (<code>Shutdown NM-Network</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchroner Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zum exakt selben Zeitpunkt <code>NmGlobalCoordinatorTime</code> erreichen alle sechs Kanäle den Zustand <code>Network silent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen:</strong></li>\n<li><code>[Nm264]</code>: Festlegung und Berechnung der kanalindividuellen Verzögerungszeit (<code>Shutdown Delay Time</code>) aus <code>NmGlobalCoordinatorTime</code> abzüglich der minimalen Shutdown-Zeit des jeweiligen Kanals.</li>\n<li><code>[Nm265]</code>: Definition von <code>NmGlobalCoordinatorTime</code> als Obergrenze für den koordinierten Shutdown aller Netze einschließlich geschachtelter Verbindungen (<code>nested connections</code>).</li>\n<li><code>[Nm266]</code>: Aktive und passive NM-Koordinatoren müssen die Verzögerungstimer zurücksetzen, falls der Shutdown durch Kommunikationsanforderungen abgebrochen wird.</li>\n<li><code>[Nm267]</code>: Bei Abbruch des Shutdowns muss das SleepReady-Bit über <code>&lt;BusNm&gt;_SetSleepReadyBit(Nm_Channel, 0)</code> auf allen aktiv koordinierten Kanälen zurückgesetzt werden.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li>Bei geschachtelten Gateways (<code>GW1 -&gt; GW2 -&gt; GW3</code>) muss die Weiterleitung des <code>SleepReady</code>-Bits von passiven an aktive Kanäle mit minimaler Latenz erfolgen, um Timing-Abweichungen innerhalb von <code>NmGlobalCoordinatorTime</code> zu vermeiden.</li>\n<li>Für passiv koordinierte Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) darf keine <code>Shutdown Delay Time</code> konfiguriert werden (Wert 0), da deren Deaktivierung direkt an die koordinierende Gegenstelle gekoppelt ist.</li>\n</ul>"}], "trans": [{"from": "FIG-59b9bdcf75475f01", "to": "FIG-74a5140d9ac21921", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Netzwerktopologie & Akteure:</strong> Ersetzung der drei abstrakten Gateway-Knoten (<code>Active Gateway</code>, <code>Passive Gateway1</code>, <code>Passive Gateway2</code>) durch ein konkretes kaskadiertes Gateway-Szenario (<code>GW1</code>, <code>GW2</code>, <code>GW3</code>) mit sechs koordinierten Kanälen (<code>GW1 Network1 actively coord. chnl</code>, <code>GW1 Network2 actively coord. chnl</code>, <code>GW2 Network2 passively coord. chnl</code>, <code>GW2 Network3 actively coord. chnl</code>, <code>GW3 Network3 passively coord. chnl</code>, <code>GW3 Network4 actively coord. chnl</code>).</li>\n<li><strong>Triggerevents & Verhaltensannotationen:</strong> Ergänzung formaler UML-Zustands- und Aktionsbeschriftungen:</li>\n<li>Globaler Starttrigger: <code>[ready to shutdown on all channels]</code></li>\n<li>Initialisierung / Koordination: <code>{set SleepReady bit, start Shutdown}</code></li>\n<li>Weiterleitung auf passiven Kanälen: <code>[receive SleepReady bit] {forward to actively Chnl}</code></li>\n<li>Phasenwechsel nach Delay-Ablauf: <code>last NM vote</code> (bzw. <code>last Nm vote</code> auf GW3 Network4)</li>\n<li><strong>Parameter & Timer-Benennung:</strong> Umbenennung von <code>coordination delay timer</code> in <code>Shutdown Delay Time</code>.</li>\n<li><strong>Phasenbenennung:</strong> Umbenennung von <code>Shutdown NM-Cluster</code> in <code>Shutdown NM-Network</code>.</li>\n<li><strong>Globaler Zeitparameter:</strong> Umbenennung von <code>Nm_GlobalCoordinatorShutdownTime</code> in <code>NmGlobalCoordinatorTime</code>.</li>\n<li><strong>Ablauf- und Timing-Struktur:</strong> Die passiv koordinierten Kanäle (<code>GW2 Network2</code>, <code>GW3 Network3</code>) besitzen keine Verzögerungszeit (<code>Shutdown Delay Time</code> = 0) und leiten den Shutdown unmittelbar bei Empfang des SleepReady-Bits ein.</li>\n</ul>"}, {"from": "FIG-74a5140d9ac21921", "to": "FIG-00bce61309d6a776", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-00bce61309d6a776", "to": "FIG-0e3f32c265898c55", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0e3f32c265898c55", "to": "FIG-00bce61309d6a776", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-00bce61309d6a776", "to": "FIG-d34986b7783fb519", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d34986b7783fb519", "to": "FIG-0e3f32c265898c55", "fr": "R22-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0e3f32c265898c55", "to": "FIG-64a4da16e22aa2e4", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
